namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    public int ForGoldCustomer(int subtotalCents)
    {
        return subtotalCents;
    }
}
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class GoldCustomerDiscountTests
{
    [Fact]
    public void GoldCustomerPaysTheApprovedShareOfTheSubtotal()
    {
        var useCase = new CalculatePayableTotal();
        _ = useCase.ForGoldCustomer(10_000);

        Assert.Fail("discount not implemented yet");
    }
}
Feature: Loyalty discount

  Scenario: Gold customer receives the approved discount
    Given a Gold customer has an order subtotal of 100.00
    When checkout calculates the payable total
    Then the payable total is 95.00
